#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, K;
    cin >> N >> K;

    vector<int> a(N), values;
    for (int &x : a) cin >> x;

    if (K == 0) {
        cout << N;
        return 0;
    }

    values = a;
    sort(values.begin(), values.end());
    values.erase(unique(values.begin(), values.end()), values.end());

    vector<int> id(N);
    for (int i = 0; i < N; ++i) {
        id[i] = lower_bound(values.begin(), values.end(), a[i]) - values.begin();
    }

    int M = values.size();
    vector<int> nextPosition(N), last(M, N + 1);

    for (int i = N - 1; i >= 0; --i) {
        nextPosition[i] = last[id[i]];
        last[id[i]] = i;
    }

    vector<bool> inCache(M, false);
    vector<int> currentNext(M, N + 1);
    priority_queue<pair<int, int>> pq;

    int cacheSize = 0;
    int ans = 0;

    for (int i = 0; i < N; ++i) {
        int value = id[i];

        if (!inCache[value]) {
            ++ans;

            if (cacheSize == K) {
                while (!pq.empty()) {
                    auto [position, candidate] = pq.top();
                    if (inCache[candidate] && currentNext[candidate] == position)
                        break;
                    pq.pop();
                }

                int removed = pq.top().second;
                pq.pop();
                inCache[removed] = false;
                --cacheSize;
            }

            inCache[value] = true;
            ++cacheSize;
        }

        currentNext[value] = nextPosition[i];
        pq.push({currentNext[value], value});
    }

    cout << ans;
    return 0;
}

