int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, K;
    cin >> N >> K;

    vector<int> a(N + 1), nextOccurrence(N + 1, N + 1);
    unordered_map<int, int> lastPosition;

    for (int i = 1; i <= N; ++i) {
        cin >> a[i];
    }

    for (int i = N; i >= 1; --i) {
        auto it = lastPosition.find(a[i]);
        if (it != lastPosition.end()) {
            nextOccurrence[i] = it->second;
        }
        lastPosition[a[i]] = i;
    }

    if (K == 0) {
        cout << N;
        return 0;
    }

    unordered_set<int> cache;
    unordered_map<int, int> currentNext;
    priority_queue<pair<int, int>> pq;

    int ans = 0;

    for (int i = 1; i <= N; ++i) {
        int value = a[i];

        if (cache.find(value) == cache.end()) {
            ++ans;

            if (static_cast<int>(cache.size()) == K) {
                while (!pq.empty()) {
                    auto [nextPos, cachedValue] = pq.top();
                    if (cache.count(cachedValue) &&
                        currentNext[cachedValue] == nextPos) {
                        break;
                    }
                    pq.pop();
                }

                int evictedValue = pq.top().second;
                pq.pop();
                cache.erase(evictedValue);
                currentNext.erase(evictedValue);
            }

            cache.insert(value);
        }

        currentNext[value] = nextOccurrence[i];
        pq.push({nextOccurrence[i], value});
    }

    cout << ans;
    return 0;
}

