        lastPosition[a[i]] = i;
    }

    if (K == 0) {
        cout << N;
        return 0;
    }

    set<pair<int, int>> cacheOrder;
    unordered_map<int, int> cache;
    int ans = 0;

    for (int i = 1; i <= N; ++i) {
        int value = a[i];
        auto it = cache.find(value);

        if (it != cache.end()) {
            cacheOrder.erase({it->second, value});
            it->second = nextOccurrence[i];
            cacheOrder.insert({nextOccurrence[i], value});
        } else {
            ++ans;

            if (static_cast<int>(cache.size()) == K) {
                auto victim = prev(cacheOrder.end());
                cache.erase(victim->second);
                cacheOrder.erase(victim);
            }

            cache[value] = nextOccurrence[i];
            cacheOrder.insert({nextOccurrence[i], value});
        }
    }

    cout << ans;
    return 0;
}

