int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, K;
    cin >> N >> K;

    vector<int> a(N + 1), nxt(N + 1);
    for (int i = 1; i <= N; ++i) cin >> a[i];

    unordered_map<int, int> last;
    last.reserve(N * 2 + 1);

    for (int i = N; i >= 1; --i) {
        auto it = last.find(a[i]);
        nxt[i] = (it == last.end() ? N + 1 : it->second);
        last[a[i]] = i;
    }

    set<pair<int, int>> cacheByNextUse;
    unordered_map<int, int> cached;
    cached.reserve(K * 2 + 1);

    int ans = 0;

    for (int i = 1; i <= N; ++i) {
        auto it = cached.find(a[i]);

        if (it != cached.end()) {
            cacheByNextUse.erase({it->second, a[i]});
            it->second = nxt[i];
            cacheByNextUse.insert({nxt[i], a[i]});
            continue;
        }

        ++ans;
        if (K == 0) continue;

        if (static_cast<int>(cached.size()) == K) {
            auto evict = prev(cacheByNextUse.end());
            cached.erase(evict->second);
            cacheByNextUse.erase(evict);
        }

        cached[a[i]] = nxt[i];
        cacheByNextUse.insert({nxt[i], a[i]});
    }

    cout << ans;
    return 0;
}

